type CompositionGroup={key:string;label:string;count:number;color:string};
type TreemapCell={group:CompositionGroup;x:number;y:number;width:number;height:number};
function layoutTreemap(groups:CompositionGroup[],x=0,y=0,width=1000,height=360):TreemapCell[]{
  if(!groups.length)return [];
  if(groups.length===1)return [{group:groups[0],x,y,width,height}];
  const total=groups.reduce((sum,group)=>sum+group.count,0);
  let split=1,firstTotal=groups[0].count,bestDifference=Math.abs(total/2-firstTotal);
  for(let i=1;i<groups.length-1;i++){
    firstTotal+=groups[i].count;
    const difference=Math.abs(total/2-firstTotal);
    if(difference<bestDifference){bestDifference=difference;split=i+1;}
  }
  const first=groups.slice(0,split),second=groups.slice(split),firstWeight=first.reduce((sum,group)=>sum+group.count,0),fraction=firstWeight/total;
  if(width>=height){const firstWidth=width*fraction;return [...layoutTreemap(first,x,y,firstWidth,height),...layoutTreemap(second,x+firstWidth,y,width-firstWidth,height)];}
  const firstHeight=height*fraction;return [...layoutTreemap(first,x,y,width,firstHeight),...layoutTreemap(second,x,y+firstHeight,width,height-firstHeight)];
}
